import{_ as e,o as t,c as i,a5 as l}from"./chunks/framework.C1a7WKBV.js";const u=JSON.parse('{"title":"效率与省钱技巧","description":"模型分级、上下文控制和额度分配——同样的费用跑出更多有效产出。","frontmatter":{"title":"效率与省钱技巧","description":"模型分级、上下文控制和额度分配——同样的费用跑出更多有效产出。"},"headers":[],"relativePath":"tips/token-efficiency.md","filePath":"tips/token-efficiency.md","lastUpdated":1788838685000}'),o={name:"tips/token-efficiency.md"};function r(d,a,h,c,n,s){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="效率与省钱技巧" tabindex="-1">效率与省钱技巧 <a class="header-anchor" href="#效率与省钱技巧" aria-label="Permalink to &quot;效率与省钱技巧&quot;">​</a></h1><p>用第三方接口按用量计费，浪费主要来自三个地方：该用小模型的场景用了大模型、上下文塞了太多无关内容、无效返工。对症下药就够了。</p><p>用第三方接口按用量计费，浪费主要来自三个地方：该用小模型的场景用了大模型、上下文塞了太多无关内容、无效返工。对症下药就够了。</p><blockquote><p>本文聚焦费用。会话与上下文如何影响<strong>产出质量</strong>，见《<a href="/tips/ai-coding-principles">通用 AI 编程方法论</a>》。</p></blockquote><h2 id="_1-模型分级使用" tabindex="-1">1. 模型分级使用 <a class="header-anchor" href="#_1-模型分级使用" aria-label="Permalink to &quot;1. 模型分级使用&quot;">​</a></h2><h3 id="_1-1-基本原则" tabindex="-1">1.1 基本原则 <a class="header-anchor" href="#_1-1-基本原则" aria-label="Permalink to &quot;1.1 基本原则&quot;">​</a></h3><p>不是所有任务都值得用旗舰模型。按任务难度选模型，费用能差出数倍。</p><h3 id="_1-2-任务与模型匹配参考" tabindex="-1">1.2 任务与模型匹配参考 <a class="header-anchor" href="#_1-2-任务与模型匹配参考" aria-label="Permalink to &quot;1.2 任务与模型匹配参考&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务类型</th><th>建议</th></tr></thead><tbody><tr><td>改文案、写注释、简单格式化</td><td>轻量模型足够</td></tr><tr><td>单文件的小功能、修小 bug</td><td>中档模型</td></tr><tr><td>跨文件重构、架构设计、疑难 bug</td><td>旗舰模型</td></tr></tbody></table><h3 id="_1-3-在客户端里切换" tabindex="-1">1.3 在客户端里切换 <a class="header-anchor" href="#_1-3-在客户端里切换" aria-label="Permalink to &quot;1.3 在客户端里切换&quot;">​</a></h3><ul><li>Claude Code：会话内用 <code>/model</code> 切换，或启动时 <code>claude --model &lt;模型名&gt;</code>。</li><li>Codex CLI：<code>/model</code> 命令选择当前会话模型。</li><li>Cursor：编辑器右下角模型选择器直接切换。</li></ul><p>常见节奏：用中档模型做探索和常规开发，卡住了再切旗舰模型攻坚。</p><h2 id="_2-控制上下文成本" tabindex="-1">2. 控制上下文成本 <a class="header-anchor" href="#_2-控制上下文成本" aria-label="Permalink to &quot;2. 控制上下文成本&quot;">​</a></h2><h3 id="_2-1-输入输出都在花钱" tabindex="-1">2.1 输入输出都在花钱 <a class="header-anchor" href="#_2-1-输入输出都在花钱" aria-label="Permalink to &quot;2.1 输入输出都在花钱&quot;">​</a></h3><p>每次请求都会把上下文重新发送一遍。长会话滚到几万 token 后，每一轮的费用都在放大。</p><h3 id="_2-2-省上下文的习惯" tabindex="-1">2.2 省上下文的习惯 <a class="header-anchor" href="#_2-2-省上下文的习惯" aria-label="Permalink to &quot;2.2 省上下文的习惯&quot;">​</a></h3><p>会话管理的基本做法（新任务开新会话、让 AI 搜索定位文件、长会话总结后续接）与《<a href="/tips/ai-coding-principles">通用 AI 编程方法论</a>》第 2 节相同——那篇讲质量，这里只补两条与费用直接相关的：</p><ul><li>每次请求都会重发整个上下文。别把上一轮的长回答原样复制回来继续问，提炼要点再带进来。</li><li>多次处理同一批文件时，让 AI 记住路径清单直接复用，而不是每轮重新搜索一遍目录。</li></ul><h3 id="_2-3-善用压缩与总结" tabindex="-1">2.3 善用压缩与总结 <a class="header-anchor" href="#_2-3-善用压缩与总结" aria-label="Permalink to &quot;2.3 善用压缩与总结&quot;">​</a></h3><p>Claude Code 上下文快满时会自动压缩（compact），也可以手动 <code>/compact</code> 主动压缩并附带重点提示，例如 <code>/compact 保留当前重构方案和剩余步骤</code>，比默认压缩更保关键信息。</p><h2 id="_3-减少无效返工" tabindex="-1">3. 减少无效返工 <a class="header-anchor" href="#_3-减少无效返工" aria-label="Permalink to &quot;3. 减少无效返工&quot;">​</a></h2><h3 id="_3-1-返工是最大的浪费" tabindex="-1">3.1 返工是最大的浪费 <a class="header-anchor" href="#_3-1-返工是最大的浪费" aria-label="Permalink to &quot;3.1 返工是最大的浪费&quot;">​</a></h3><p>一次方向错误的生成，烧掉的 token 加上人工检查时间，比事先写清楚需求贵得多。返工两次的成本足够你写好一份完整需求。</p><h3 id="_3-2-性价比最高的三个投入" tabindex="-1">3.2 性价比最高的三个投入 <a class="header-anchor" href="#_3-2-性价比最高的三个投入" aria-label="Permalink to &quot;3.2 性价比最高的三个投入&quot;">​</a></h3><ol><li>维护好项目规则文件（<code>CLAUDE.md</code> / <code>AGENTS.md</code>），一次投入长期摊薄。</li><li>复杂任务先要方案再实现，方向错了改方案比改代码便宜。</li><li>让 AI 交付前自查并跑验证命令，减少来回拉锯。</li></ol><h2 id="_4-额度分配策略" tabindex="-1">4. 额度分配策略 <a class="header-anchor" href="#_4-额度分配策略" aria-label="Permalink to &quot;4. 额度分配策略&quot;">​</a></h2><h3 id="_4-1-看清消耗去向" tabindex="-1">4.1 看清消耗去向 <a class="header-anchor" href="#_4-1-看清消耗去向" aria-label="Permalink to &quot;4.1 看清消耗去向&quot;">​</a></h3><p>定期在 STJAPI 控制台查看用量明细，弄清楚额度花在哪些项目、哪些时段。发现某个项目消耗异常，通常是会话管理出了问题。</p><h3 id="_4-2-分配建议" tabindex="-1">4.2 分配建议 <a class="header-anchor" href="#_4-2-分配建议" aria-label="Permalink to &quot;4.2 分配建议&quot;">​</a></h3><ul><li>日常探索与学习：用低价模型，舍得用。</li><li>正式开发与攻坚：留给旗舰模型，用在刀刃上。</li><li>批量机械任务（格式化、批量改名）：优先考虑脚本化，能不用 AI 就不用。</li></ul><h3 id="_4-3-建立自己的用量心视" tabindex="-1">4.3 建立自己的用量心视 <a class="header-anchor" href="#_4-3-建立自己的用量心视" aria-label="Permalink to &quot;4.3 建立自己的用量心视&quot;">​</a></h3><p>每周扫一眼：单次会话平均消耗有没有异常大的？有没有明明是小任务却用了旗舰模型的情况？持续校准，同样的额度能多跑一大截。</p><h2 id="_5-一页速查" tabindex="-1">5. 一页速查 <a class="header-anchor" href="#_5-一页速查" aria-label="Permalink to &quot;5. 一页速查&quot;">​</a></h2><p>相关阅读：《<a href="/tips/ai-coding-principles">通用 AI 编程方法论</a>》（质量视角的上下文管理）、《<a href="/tips/roadmap">从零到驾驭 AI：成长路径</a>》第五阶段（把省钱习惯固化为流程）。</p><ul><li>按任务难度选模型，探索用轻量、攻坚用旗舰。</li><li>新任务新会话，让 AI 自己搜索而不是贴代码。</li><li>长会话主动 <code>/compact</code>，并提示保留重点。</li><li>规则文件与先方案后实现，是对冲返工最便宜的保险。</li><li>每周看一次用量明细，校准自己的习惯。</li></ul>',35)])])}const _=e(o,[["render",r]]);export{u as __pageData,_ as default};
